#nullable enable
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;

// Generated by Claude Opus 5.5
// Records the player's mouse each attempt and replays past attempts as "ghost" cursors.
public partial class GameManager
{
    private const float GHOST_CONTACT_RADIUS = 0.25f;

    [Tooltip("The sprite used to show the cursor of a past attempt.")]
    public SpriteRenderer? ghostCursor = null;

    // Raised when the game ends. The argument is true if the game was won.
    public event Action<bool>? GameEnded;

    private List<MouseSample> recording = new();

    private readonly List<Ghost> ghosts = new();

    // Generated by Claude Opus 5.5
    // Records this frame's mouse state, replays the ghosts, and loses the game if the player touches one.
    private void UpdateGhosts(Mouse mouse)
    {
        float time = this.TotalSeconds - this.SecondsRemaining;
        Vector2 position = Camera.main.ScreenToWorldPoint(mouse.position.ReadValue());
        this.recording.Add(new MouseSample(time, position, mouse.leftButton.isPressed));

        foreach (Ghost ghost in this.ghosts)
        {
            // Replay every sample this ghost has reached since last frame
            while (ghost.index + 1 < ghost.samples.Count && ghost.samples[ghost.index + 1].time <= time)
            {
                ghost.index++;
                MouseSample sample = ghost.samples[ghost.index];
                if (ghost.cursor != null)
                    ghost.cursor.transform.position = sample.position;
                if (sample.pressed)
                    this.DrawAt(sample.position);
            }

            if (ghost.index < 0)
                continue;
            Vector2 ghostPosition = ghost.samples[ghost.index].position;
            if ((ghostPosition - position).sqrMagnitude <= GHOST_CONTACT_RADIUS * GHOST_CONTACT_RADIUS)
            {
                this.EndGame(false);
                return;
            }
        }
    }

    // Generated by Claude Opus 5.5
    // Turns the current attempt into a ghost and restarts the operation alongside all ghosts.
    private void Rewind()
    {
        SpriteRenderer? cursor = this.ghostCursor != null ? Instantiate(this.ghostCursor) : null;
        this.ghosts.Add(new Ghost(this.recording, cursor));
        this.recording = new();
        foreach (Ghost ghost in this.ghosts)
            ghost.index = -1;

        this.SecondsRemaining = this.TotalSeconds;
        this.forgivePosition = null;
        this.completedShapes.Clear();
        foreach (ShapeBehaviour shape in this.shapes)
            shape.Reset();
        this.ClearStrokes();
    }

    // Generated by Claude Opus 5.5
    // One frame of mouse input. Time is seconds since the attempt started.
    private readonly struct MouseSample
    {
        public readonly float time;
        public readonly Vector2 position;
        public readonly bool pressed;

        public MouseSample(float time, Vector2 position, bool pressed)
        {
            this.time = time;
            this.position = position;
            this.pressed = pressed;
        }
    }

    // Generated by Claude Opus 5.5
    // A past attempt being replayed.
    private class Ghost
    {
        public readonly List<MouseSample> samples;
        public readonly SpriteRenderer? cursor;
        public int index = -1;

        public Ghost(List<MouseSample> samples, SpriteRenderer? cursor)
        {
            this.samples = samples;
            this.cursor = cursor;
        }
    }
}
